CREATE DATABASE IF NOT EXISTS loudy_toutou CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE loudy_toutou;
CREATE TABLE IF NOT EXISTS memories (id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,description TEXT,photo_url TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS love_letters (id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bucket_items (id INT AUTO_INCREMENT PRIMARY KEY,text VARCHAR(255) NOT NULL,completed BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reasons (id INT AUTO_INCREMENT PRIMARY KEY,text TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS daily_messages (id INT AUTO_INCREMENT PRIMARY KEY,message TEXT NOT NULL,message_date DATE UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quiz_questions (id INT AUTO_INCREMENT PRIMARY KEY,question TEXT NOT NULL,options JSON NOT NULL,correct_option INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS quiz_results (id INT AUTO_INCREMENT PRIMARY KEY,score INT NOT NULL,total INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS calendar_events (id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,event_date DATE NOT NULL,notes TEXT);
CREATE TABLE IF NOT EXISTS interactions (id INT AUTO_INCREMENT PRIMARY KEY,type VARCHAR(50) NOT NULL,message TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS game_scores (id INT AUTO_INCREMENT PRIMARY KEY,game VARCHAR(60) NOT NULL,result TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS wishes (id INT AUTO_INCREMENT PRIMARY KEY,wish TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS dream_rooms (id INT AUTO_INCREMENT PRIMARY KEY,layout JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
